entries[1272893] = { ["name"] = "Xal'atath's Bargain: Ascendant", ["text"] = "Instant\nXal'atath rains down orbs of cosmic energy that attempt to grant nearby creatures Xal'atath's Gift , increasing their damage done by 5% and reducing their damage taken by 10% for 20 sec. This effect stacks.\n\nIf players disrupt these orbs they claim the power for themselves increasing their Haste and Movement speed by 2% for 30 sec. This effect stacks." }
entries[1272894] = { ["name"] = "Xal'atath's Bargain: Pulsar", ["text"] = "100 yd range\n4 sec cast\nXal'atath summons void pulsars that orbit players. After 15 sec the void pulsar releases its energy to grant creatures Xal'atath's Gift , increasing damage done by 10% and reducing damage taken by 20% for 20 sec. This effect stacks.\n\nPlayers that come into contact with a void pulsar empower players, granting them 4% Mastery and 2% Leech for 30 sec. This effect stacks." }
entries[1272895] = { ["name"] = "Xal'atath's Bargain: Voidbound", ["text"] = "100 yd range\n15 sec cast\nThe Void Emissary casts a dark prayer. When the cast completes, nearby creatures are granted Xal'atath's Gift , increasing their damage done by up to 50% and reducing their damage taken by up to 100% for 20 sec based on the amount of the Void Emissary's shield that remains.\n\nDefeating the Void Emissary empowers players, granting them 20% Versatility and 30% spell and ability cooldown rate for 30 sec." }
entries[1272896] = { ["name"] = "Xal'atath's Bargain: Devour", ["text"] = "Unlimited range\nInstant\nXal'atath tears open Devouring Rifts that consume the essence of players, inflicting Shadow damage equal to 1% of their max health every 1 sec for 15 sec and reducing their movement speed by 10%. Upon expiration, the rift releases its energy granting nearby creatures Xal'atath's Gift , increasing their damage done by 10% and reducing their damage taken by 20% for 20 sec. This effect stacks.\n\nIf the affected players receive 145770 healing or are dispelled the rift collapses empowering players. The rift grants 4% Critical strike chance and 2% increased maximum health for 30 sec. This effect stacks." }
